function update(){scheduled=false;positionNow=position();window.NexaBook?.setProgress(positionNow);$('header').classList.toggle('scrolled',scrollY>35);const chapter=Math.min(LAST,Math.floor(positionNow+.18));if(chapter!==current)displayChapter(chapter);const phase=window.NexaBook?.getPhase?.(positionNow);const turning=phase?.turning||positionNow<1.08&&positionNow>.62||positionNow>6.68;stage.classList.toggle('page-turning',!!turning);$('reading-state').textContent=turning?'TURNING THE PAGE':'TAKE A MOMENT. MAKE IT YOURS.';stage.style.setProperty('--story-progress',String(positionNow/TOTAL));$('chapter-meter').style.transform=`scaleX(${positionNow/TOTAL})`;const holdStart=chapter===0?0:chapter+.08;const holdLength=chapter===0?.62:.54;tabs[chapter].style.setProperty('--chapter-fill',String(Math.max(0,Math.min(1,(positionNow-holdStart)/holdLength))));}
function requestUpdate(){if(!scheduled){scheduled=true;requestAnimationFrame(update);}}function scrollProgress(p,smooth=true){const top=story.getBoundingClientRect().top+scrollY;scrollTo({top:top+(story.offsetHeight-innerHeight)*(Math.max(0,Math.min(TOTAL,p))/TOTAL),behavior:reduced||!smooth?'instant':'smooth'});}function go(n){n=Math.max(0,Math.min(LAST,n));scrollProgress(n===0?0:n+.22);}
