document.querySelectorAll('.book-hotspot').forEach(b=>b.addEventListener('click',()=>{b.classList.toggle('expanded');b.setAttribute('aria-expanded',String(b.classList.contains('expanded')));}));
let down=null,dragging=false;const book=$('book');book.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY,p:positionNow,chapter:current,id:e.pointerId};dragging=false;});book.addEventListener('pointermove',e=>{if(!down)return;const dx=e.clientX-down.x,dy=e.clientY-down.y;if(!dragging&&Math.abs(dx)>18&&Math.abs(dx)>Math.abs(dy)*1.3){dragging=true;book.setPointerCapture(e.pointerId);}if(dragging){if(e.cancelable)e.preventDefault();scrollProgress(down.p-dx/book.clientWidth*1.8,false);}});book.addEventListener('pointerup',e=>{if(!down)return;const dx=e.clientX-down.x;if(dragging&&Math.abs(dx)>40)go(Math.max(0,Math.min(LAST,down.chapter+(dx<0?1:-1))));if(book.hasPointerCapture?.(e.pointerId))book.releasePointerCapture(e.pointerId);down=null;dragging=false;});book.addEventListener('pointercancel',()=>{down=null;dragging=false;});document.querySelector('.chapter-control').addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const n=Math.max(0,Math.min(LAST,current+(e.key==='ArrowRight'?1:-1)));go(n);tabs[n].focus();}});
if(!reduced&&matchMedia('(hover:hover) and (pointer:fine)').matches){document.querySelectorAll('.primary-btn,.header-cta').forEach(b=>{b.addEventListener('pointermove',e=>{const r=b.getBoundingClientRect();b.style.transform=`translate(${(e.clientX-r.left-r.width/2)*.065}px,${(e.clientY-r.top-r.height/2)*.12}px)`;});b.addEventListener('pointerleave',()=>{b.style.transform='';});});const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target);}}),{threshold:.12});document.querySelectorAll('.section-heading,.about-layout,.initiative-feature,.connections-layout,.contact-layout').forEach(el=>{el.classList.add('reveal-section');observer.observe(el);});}
