let selected=null;const dialog=$('path-dialog');function showPath(key){selected=details[key];if(!selected)return;$('dialog-tag').textContent=selected.tag;$('dialog-title').textContent=selected.title;$('dialog-copy').textContent=selected.copy;$('dialog-note').textContent=selected.note;$('dialog-points').replaceChildren(...selected.points.map(p=>{const li=document.createElement('li');li.textContent=p;return li;}));dialog.showModal();}
